#!/usr/bin/env python3
"""Bring a machine up to the point where this skill can run a batch.

Separates three things that used to be discovered the hard way — in the middle of a batch, or in
the reviewer's last click:

* **Python dependencies.** Checked, and installed only with ``--install``. ``reportlab`` and
  PyMuPDF are needed by the approved write-back, so without them a machine can grade a whole
  batch and only then fail to write it back.
* **Local OCR helpers.** Generated by ``scripts/setup_local_ocr.sh`` with ``--ocr``. They are
  deliberately not packaged (they are per-machine and one of them is compiled), so a freshly
  unpacked skill has no OCR until this runs.
* **Machine-local paths.** ``--write-config`` records what resolved into ``config/local.json``, so
  the next person can see the setup instead of inferring it. Nothing here overrides a flag or an
  environment variable later: those still win.

    python3 scripts/bootstrap.py                  # report only
    python3 scripts/bootstrap.py --all            # install, generate OCR helpers, write config
    python3 scripts/bootstrap.py --install --ocr  # the two that need to actually run things
"""

from __future__ import annotations

import argparse
import importlib
import json
import os
import subprocess
import sys
from pathlib import Path

SKILL_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(SKILL_ROOT / "scripts"))

import resolve_env  # noqa: E402

# import name -> pip name, in the order a failure hurts least
DEPENDENCIES = {
    "pypdf": "pypdf",
    "PIL": "pillow",
    "openpyxl": "openpyxl",
    "reportlab": "reportlab",
    "fitz": "PyMuPDF",
}
# Needed by the approved write-back; a batch can otherwise be reviewed in full before these matter.
WRITEBACK_ONLY = {"reportlab", "fitz"}


def missing_dependencies(python: Path) -> list[str]:
    """Ask the chosen interpreter directly, rather than importing into this process."""
    program = (
        "import importlib, json, sys\n"
        f"names = {json.dumps(sorted(DEPENDENCIES))}\n"
        "missing = []\n"
        "for name in names:\n"
        "    try:\n"
        "        importlib.import_module(name)\n"
        "    except Exception:\n"
        "        missing.append(name)\n"
        "print(json.dumps(missing))\n"
    )
    completed = subprocess.run(
        [str(python), "-c", program],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if completed.returncode != 0:
        raise SystemExit(f"Could not query {python}: {completed.stderr.strip()}")
    return json.loads(completed.stdout.strip().splitlines()[-1])


def install_missing(python: Path, missing: list[str], dry_run: bool) -> dict:
    packages = [DEPENDENCIES[name] for name in missing if name in DEPENDENCIES]
    if not packages:
        return {"ran": False, "command": "", "detail": "nothing missing"}
    command = [str(python), "-m", "pip", "install", *packages]
    if dry_run:
        return {"ran": False, "command": " ".join(command), "detail": "dry run"}
    completed = subprocess.run(
        command, capture_output=True, text=True, encoding="utf-8", errors="replace"
    )
    return {
        "ran": True,
        "command": " ".join(command),
        "detail": (completed.stdout or completed.stderr).strip().splitlines()[-1] if completed.returncode == 0
        else f"failed: {(completed.stderr or completed.stdout).strip()[-300:]}",
        "ok": completed.returncode == 0,
    }


def run_ocr_setup(dry_run: bool, with_vision: bool = False) -> dict:
    script = SKILL_ROOT / "scripts" / "setup_local_ocr.sh"
    if not script.is_file():
        return {"ran": False, "detail": f"{script} not found"}
    if os.name == "nt":
        # No bash on Windows, so the shim generator cannot run there. Report what this machine
        # actually has rather than only naming two system installs: rapidocr-onnxruntime installs
        # from pip on Windows as well, which is the route to offline OCR without a system package.
        note = "no shim generator on Windows (the helper script is bash)"
        usable = [item["engine"] for item in resolve_env.ocr_inventory() if item["usable"]]
        note += (
            f"; available here: {', '.join(usable)}" if usable
            else "; install Tesseract and poppler, or pip install rapidocr-onnxruntime"
        )
        return {"ran": False, "detail": note}
    command = ["bash", str(script)] + (["--with-vision"] if with_vision else [])
    if dry_run:
        return {"ran": False, "command": " ".join(command), "detail": "dry run"}
    completed = subprocess.run(
        command,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        cwd=str(SKILL_ROOT),
    )
    tail = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "ran": True,
        "command": " ".join(command),
        "detail": tail[-1] if tail else "",
        "ok": completed.returncode == 0,
    }


def write_local_config(dry_run: bool) -> dict:
    """Record the paths that resolved, so the setup is inspectable rather than implicit."""
    entries = {
        "python": resolve_env.resolve_python(),
        "node": resolve_env.resolve_node(),
        "signature_pdf": resolve_env.resolve_signature_pdf(),
        "score_font": resolve_env.resolve_score_font(),
        "ocr_executable": resolve_env.resolve_ocr_program("tesseract"),
        "pdftoppm_executable": resolve_env.resolve_ocr_program("pdftoppm"),
    }
    payload = {
        "_generated_by": "scripts/bootstrap.py --write-config",
        "_note": "Machine-local paths. Flags and EXPERIMENT_REPORT_GRADER_* variables still win.",
    }
    for key, resolution in entries.items():
        if resolution.ok and not resolution.source.startswith("config:"):
            payload[key] = str(resolution.value)
    target = resolve_env.config_path()
    if dry_run:
        return {"ran": False, "target": str(target), "detail": "dry run", "payload": payload}
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {"ran": True, "target": str(target), "detail": f"wrote {len(payload) - 2} paths", "payload": payload}


def machine_assets() -> list[dict]:
    """Per-machine items this skill deliberately does not ship.

    ``reportlab`` is not the only thing that fails at the very end: the write-back also needs the
    teacher's signature template and a handwriting face, and OCR needs its helpers. Those are
    configuration rather than dependencies, so they are reported by name with the layer that
    answered and the ways to supply them. A machine that will grade a batch happily and then refuse
    to write it back should say so up front, not after the whole batch has been reviewed.
    """
    items = (
        (
            "signature template",
            resolve_env.resolve_signature_pdf(),
            True,
            "pass --signature-pdf, set EXPERIMENT_REPORT_GRADER_SIGNATURE_PDF, run "
            "bootstrap.py --write-config, or place a PDF at assets/signature/signature.pdf",
        ),
        (
            "score font",
            resolve_env.resolve_score_font(),
            True,
            "pass --score-font, set EXPERIMENT_REPORT_GRADER_SCORE_FONT, or add "
            '"score_font" to config/local.json',
        ),
        (
            "ocr helper",
            resolve_env.resolve_ocr_program("tesseract"),
            False,
            ("check other local drives or provide ocr_executable; verify chi_sim+eng"
             if sys.platform == "win32" else "run bootstrap.py --ocr (or scripts/setup_local_ocr.sh)"),
        ),
        (
            "pdftoppm",
            resolve_env.resolve_ocr_program("pdftoppm"),
            False,
            ("check other local drives or provide pdftoppm_executable; install Poppler only if needed"
             if sys.platform == "win32" else "install poppler, or run bootstrap.py --ocr"),
        ),
    )
    return [
        {
            "name": name,
            "ok": resolution.ok,
            "value": None if resolution.value is None else str(resolution.value),
            "source": resolution.source,
            "detail": resolution.detail,
            "critical": critical,
            "fix": fix,
        }
        for name, resolution, critical, fix in items
    ]


def run_doctor(python: Path) -> dict:
    completed = subprocess.run(
        [str(python), str(SKILL_ROOT / "scripts" / "batch_pipeline.py"), "doctor"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        cwd=str(SKILL_ROOT),
    )
    lines = completed.stdout.strip().splitlines()
    payload = lines[-1] if lines else "{}"
    try:
        parsed = json.loads(payload)
    except ValueError:
        parsed = {"ok": False, "raw": payload}
    return {"ok": bool(parsed.get("ok")), "missing": parsed.get("missing", []), "exit": completed.returncode}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--python", help="interpreter to inspect and install into (default: this one)")
    parser.add_argument("--install", action="store_true", help="pip install what is missing")
    parser.add_argument("--ocr", action="store_true", help="generate the local OCR helpers")
    parser.add_argument(
        "--with-vision",
        action="store_true",
        help="also build the macOS Vision helper (macOS only; implies --ocr)",
    )
    parser.add_argument("--write-config", action="store_true", help="record resolved paths in config/local.json")
    parser.add_argument("--all", action="store_true", help="--install --ocr --write-config")
    parser.add_argument("--dry-run", action="store_true", help="show the commands without running them")
    parser.add_argument("--no-doctor", action="store_true")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()
    if args.all:
        args.install = args.ocr = args.write_config = True
    if args.with_vision:
        # Explicit opt-in only. Auto uses the rapidocr-backed shim, so --all sets up the default
        # engine; Vision stays a deliberate alternative (--ocr-engine vision) rather than
        # something that gets built behind the user's back.
        args.ocr = True

    python = Path(args.python).expanduser().resolve() if args.python else Path(sys.executable)
    report: dict = {"python": str(python), "actions": {}}

    missing = missing_dependencies(python)
    report["actions"]["dependencies"] = {
        "missing": missing,
        "blocking_writeback": sorted(WRITEBACK_ONLY & set(missing)),
    }
    if args.install and missing:
        report["actions"]["install"] = install_missing(python, missing, args.dry_run)

    assets = machine_assets()
    report["machine_assets"] = assets
    unresolved_critical = [item for item in assets if item["critical"] and not item["ok"]]

    if args.ocr:
        report["actions"]["ocr"] = run_ocr_setup(args.dry_run, args.with_vision)
    if args.write_config:
        report["actions"]["config"] = write_local_config(args.dry_run)
    if not args.no_doctor:
        report["doctor"] = run_doctor(python)

    # Reported after the actions, so it describes the machine as it now stands: computing it
    # earlier made a successful --ocr run still print "not wired" from the pre-setup state.
    # The agent is the one that has to tell the teacher what their local OCR is, so this is
    # reported whether or not --ocr ran.
    report["ocr"] = resolve_env.ocr_report()

    report["ok"] = (
        bool(report.get("doctor", {}).get("ok", True))
        and not unresolved_critical
        and not (
            (args.install and not report["actions"].get("install", {}).get("ok", True))
            or (args.ocr and not report["actions"].get("ocr", {}).get("ok", True))
        )
    )

    if args.json:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    else:
        print(f"interpreter: {report['python']}")
        if missing:
            print(f"  missing modules: {', '.join(missing)}"
                  + (f"  (write-back needs: {', '.join(sorted(WRITEBACK_ONLY & set(missing)))})"
                     if WRITEBACK_ONLY & set(missing) else ""))
            if not args.install:
                print(f"  install with: {python} -m pip install {' '.join(DEPENDENCIES[n] for n in missing)}")
        else:
            print("  dependencies: all present")
        for name, action in report["actions"].items():
            if name == "dependencies":
                continue
            print(f"  {name}: {action.get('detail', '')}")
        print("  per-machine assets (never bundled):")
        for item in assets:
            if item["ok"]:
                print(f"    [ok  ] {item['name']:<18} {item['value']}  [{item['source']}]")
            else:
                marker = "BLOCK" if item["critical"] else "opt  "
                # The reason a path failed to resolve was already computed; dropping it is what made
                # "a stale config pointed at a missing file" look identical to "nothing installed".
                why = f" ({item['detail']})" if item.get("detail") else ""
                print(f"    [{marker}] {item['name']:<18} unresolved — {item['fix']}{why}")
        ocr = report.get("ocr") or {}
        if ocr:
            print("  local OCR (this machine):")
            print(f"    default engine:  {ocr['default_engine']} (the tesseract-compatible shim)")
            print(f"    platform-native: {ocr['native_engine']}")
            for item in ocr["available"]:
                where = item["location"] or item["detail"] or "-"
                version = f" {item['version']}" if item["version"] else ""
                tags = ", ".join(
                    tag for tag in (
                        "native" if item.get("native") else "",
                        "usable" if item["usable"] else "unavailable",
                        "wired" if item["wired"] else "not wired",
                    ) if tag
                )
                print(f"    {item['engine']:<10} {tags:<24} {where}{version}")
            if ocr["wired"]:
                line = f"    in use: {ocr['engine']}"
                if ocr["vision_wired"] and ocr["engine"] != "vision":
                    line += "   (Vision is also wired: --ocr-engine vision)"
                print(line)
            elif ocr["enable_command"]:
                print(f"    in use: none yet — enable with: {ocr['enable_command']}")
            else:
                print("    in use: none — no local OCR found; text-only grading still works")
        if "doctor" in report:
            print(f"  doctor: {'ok' if report['doctor']['ok'] else 'missing ' + str(report['doctor']['missing'])}")
        if unresolved_critical:
            print(
                "  NOTE: the write-back needs the items marked BLOCK. Grading, review and Excel "
                "work without them; approving a report will fail until they are configured."
            )
    return 0 if report["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
